int lengthOfLastWord(string s) {
    int i = (int)s.size() - 1;
    while (i >= 0 && s[i] == ' ') --i;           // skip trailing spaces
    int len = 0;
    while (i >= 0 && s[i] != ' ') { ++len; --i; }
    return len;
}

public int lengthOfLastWord(String s) {
    int i = s.length() - 1;
    while (i >= 0 && s.charAt(i) == ' ') i--;    // skip trailing spaces
    int len = 0;
    while (i >= 0 && s.charAt(i) != ' ') { len++; i--; }
    return len;
}
